select
  id, patient_id, study_id, create_time, update_time, diagnosis_type, diagnosis_no, diagnosis_desc, diagnosis_date, final_check_doctor, check_desc, check_doctor, check_date, health_advice, dietary_advice, sports_advice, treatment_recommendations
from td_diagnosis


        and id = #{id}


        and patient_id = #{patientId}


        and study_id = #{studyId}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and diagnosis_type = #{diagnosisType}


        and diagnosis_no = #{diagnosisNo}


        and diagnosis_desc = #{diagnosisDesc}


        and diagnosis_date = #{diagnosisDate}


        and final_check_doctor = #{finalCheckDoctor}


        and check_desc = #{checkDesc}


        and check_doctor = #{checkDoctor}


        and check_date = #{checkDate}


        and health_advice = #{healthAdvice}


        and dietary_advice = #{dietaryAdvice}


        and sports_advice = #{sportsAdvice}


        and treatment_recommendations = #{treatmentRecommendations}


limit #{pageable.offset}, #{pageable.pageSize}

