select id, patient_id, study_id, create_time, update_time, diagnosis_type, diagnosis_no, diagnosis_desc, diagnosis_date, final_check_doctor, check_desc, check_doctor, check_date, health_advice, dietary_advice, sports_advice, treatment_recommendations,result_date from td_diagnosis
